from datetime import date, timedelta


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays else set()
        # (employee, year) -> days used
        self._used: dict[tuple[str, int], int] = {}

    def _count_leave_days(self, start: date, end: date) -> int:
        count = 0
        current = start
        while current <= end:
            # Count weekdays (Mon-Fri) that aren't holidays
            if current.weekday() < 5 and current not in self.holidays:
                count += 1
            current += timedelta(days=1)
        return count

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        if end < start:
            raise ValueError("End date cannot be before start date")

        if (start - today).days < 3:
            raise ValueError("Leave must be requested at least 3 days in advance")

        # Count days per year (may span across years)
        days_by_year: dict[int, int] = {}
        current = start
        while current <= end:
            if current.weekday() < 5 and current not in self.holidays:
                days_by_year[current.year] = days_by_year.get(current.year, 0) + 1
            current += timedelta(days=1)

        total = sum(days_by_year.values())

        # Check remaining for each affected year
        for year, needed in days_by_year.items():
            used = self._used.get((employee, year), 0)
            if used + needed > self.days_per_year:
                raise ValueError(
                    f"Insufficient leave remaining for {employee} in {year}"
                )

        # Commit
        for year, needed in days_by_year.items():
            key = (employee, year)
            self._used[key] = self._used.get(key, 0) + needed

        return total

    def remaining(self, employee: str, year: int) -> int:
        used = self._used.get((employee, year), 0)
        return self.days_per_year - used
